package dev.zomboid.isotacz;
public final class BackpackInteraction {
 static boolean backpack(Object object){if(object==null)return false;for(Class<?> type=object.getClass();type!=null;type=type.getSuperclass())if(type.getName().startsWith("net.p3pp3rf1y.sophisticatedbackpacks.backpack.Backpack"))return true;return false;}
 public static boolean placed(Object world,Object pos){if(world==null||pos==null||!R.yes(R.call(world,"isInWorldBounds",pos)))return false;return backpack(R.call(R.call(world,"getBlockState",pos),"getBlock"))&&!R.yes(R.call(R.type("com.cleannrooster.dungeons_iso.util.InteractionTargeting"),"isBlacklisted",world,pos));}
 public static void open(Object client,Object hit){Object player=R.get(client,"player"),mode=R.get(client,"gameMode"),hands=R.type("net.minecraft.world.InteractionHand");R.set(client,"hitResult",hit);boolean block=R.call(hit,"getType").toString().equals("BLOCK");R.set(client,"crosshairPickEntity",block?null:R.call(hit,"getEntity"));for(String name:new String[]{"MAIN_HAND","OFF_HAND"}){Object hand=R.get(hands,name);Object result=block?R.call(mode,"useItemOn",player,hand,hit):R.call(mode,"interact",player,R.call(hit,"getEntity"),hand);if(done(result,player,hand))return;Object stack=R.call(player,"getItemInHand",hand);if(backpack(R.call(stack,"getItem"))){result=R.call(mode,"useItem",player,hand);if(done(result,player,hand))return;}}}
 static boolean done(Object result,Object player,Object hand){if(R.yes(R.call(result,"shouldSwing")))R.call(player,"swing",hand);return R.yes(R.call(result,"consumesAction"))||result.toString().equals("FAIL");}
}
